import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import org.springframework.beans.factory.ObjectProvider;

@Component
@Scope("prototype")  // new instance every time
public class InvoiceGenerator {
    private final List<String> lineItems = new ArrayList<>();
    private BigDecimal totalAmount = BigDecimal.ZERO;

    public void addItem(String item, BigDecimal price) {
        lineItems.add(item);  // mutable state
        totalAmount = totalAmount.add(price);
    }

    public byte[] generatePDF() {
        // build PDF from lineItems and totalAmount
        return new byte[0];
    }
}

@Service  // singleton
public class BillingService {
    private final ObjectProvider<InvoiceGenerator> generatorProvider;

    public BillingService(ObjectProvider<InvoiceGenerator> generatorProvider) {
        this.generatorProvider = generatorProvider;  // solution to prototype-in-singleton trap
    }

    public byte[] createInvoice(Long orderId) {
        var generator = generatorProvider.getObject();  // fresh instance here
        generator.addItem("Item A", new BigDecimal("10.00"));
        generator.addItem("Item B", new BigDecimal("25.50"));
        return generator.generatePDF();
    }
}
