// Prototype bean with state
@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class RequestProcessor {
    private final String requestId = UUID.randomUUID().toString();

    public String process(String data) {
        return "Request " + requestId + " processed: " + data;
    }
}

// WRONG: Singleton injects prototype directly
@Service
class OrderService {
    private final RequestProcessor processor; // Same instance forever

    public OrderService(RequestProcessor processor) {
        this.processor = processor;
    }

    public String handleOrder(String order) {
        return processor.process(order); // Always same requestId
    }
}

// CORRECT: Use ObjectProvider for lazy lookup
@Service
class ImprovedOrderService {
    private final ObjectProvider<RequestProcessor> processorProvider;

    public ImprovedOrderService(ObjectProvider<RequestProcessor> provider) {
        this.processorProvider = provider;
    }

    public String handleOrder(String order) {
        var processor = processorProvider.getObject(); // Fresh instance
        return processor.process(order); // Different requestId each call
    }
}
